module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output done
);

    typedef enum logic [1:0] {
        S_BYTE1 = 2'd0,
        S_BYTE2 = 2'd1,
        S_BYTE3 = 2'd2,
        S_DONE  = 2'd3
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S_BYTE1;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            S_BYTE1: begin
                if (in[3]) begin
                    next_state = S_BYTE2;
                end
            end
            S_BYTE2: begin
                next_state = S_BYTE3;
            end
            S_BYTE3: begin
                next_state = S_DONE;
            end
            S_DONE: begin
                if (in[3]) begin
                    next_state = S_BYTE2;
                end else begin
                    next_state = S_BYTE1;
                end
            end
            default: next_state = S_BYTE1;
        endcase
    end

    assign done = (state == S_DONE);

endmodule

